/// Convert a command-line argument with the same prefix rules as C's `atoi`.
///
/// Leading C whitespace and an optional sign are accepted. Conversion stops at
/// the first non-digit, and a string with no digits converts to zero.
pub fn atoi_i32(value: &str) -> i32 {
    let bytes = value.as_bytes();
    let mut position = 0;

    while position < bytes.len() && matches!(bytes[position], b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) {
        position += 1;
    }

    let mut negative = false;
    if position < bytes.len() && (bytes[position] == b'+' || bytes[position] == b'-') {
        negative = bytes[position] == b'-';
        position += 1;
    }

    let mut number = 0_i64;
    while position < bytes.len() && bytes[position].is_ascii_digit() {
        number = number.saturating_mul(10).saturating_add(i64::from(bytes[position] - b'0'));
        position += 1;
    }

    if negative {
        number = -number;
    }

    number as i32
}

