args.old_string:
fn sort_linked(&mut self, start: usize) -> usize {
    let mut in_size = 1_usize;
    let mut list: Option<usize> = Some(start);

    loop {
        let mut p: Option<usize> = list;
        let mut tail: Option<usize> = None;
        let mut num_merges = 0_usize;
        list = None;

        while let Some(p_id) = p {
            num_merges += 1;
            let mut q = Some(p_id);
            let mut p_size = 0_usize;

            for _ in 0..in_size {
                p_size += 1;
                q = self.nodes[q.expect("q is always present while counting")].next_z;
                if q.is_none() {
                    break;
                }
            }

            let mut q_size = in_size;
            let mut p_cursor = Some(p_id);

            while p_size > 0 || (q_size > 0 && q.is_some()) {
                let element;
                if p_size == 0 {
                    element = q.expect("q-side merge requires q");
                    q = self.nodes[element].next_z;
                    q_size -= 1;
                } else if q_size == 0 || q.is_none() {
                    element = p_cursor.expect("p-side merge requires p");
                    p_cursor = self.nodes[element].next_z;
                    p_size -= 1;
                } else {
                    let p_element = p_cursor.expect("p-side merge requires p");
                    let q_element = q.expect("q-side merge requires q");
                    if self.nodes[p_element].z <= self.nodes[q_element].z {
                        element = p_element;
                        p_cursor = self.nodes[element].next_z;
                        p_size -= 1;
                    } else {
                        element = q_element;
                        q = self.nodes[element].next_z;
                        q_size -= 1;
                    }
                }

                if let Some(tail_id) = tail {
                    self.nodes[tail_id].next_z = Some(element);
                } else {
                    list = Some(element);
                }
                self.nodes[element].prev_z = tail;
                tail = Some(element);
            }

            p = q;
        }

        if let Some(tail_id) = tail {
            self.nodes[tail_id].next_z = None;
        }
        if num_merges <= 1 {
            return list.unwrap_or(start);
        }
        in_size *= 2;
    }
}

args.new_string:
fn sort_linked(&mut self, start: usize) -> usize {
    let mut ordered = Vec::with_capacity(self.nodes.len());
    let mut id = start;
    loop {
        ordered.push(id);
        id = self.nodes[id].next;
        if id == start {
            break;
        }
    }

    // Keep this sort stable so equal z-values retain their original ring
    // order, matching the reference implementation's merge sort.
    ordered.sort_by_key(|&node_id| self.nodes[node_id].z);

    for position in 0..ordered.len() {
        let node_id = ordered[position];
        self.nodes[node_id].prev_z = position.checked_sub(1).map(|previous| ordered[previous]);
        self.nodes[node_id].next_z = ordered.get(position + 1).copied();
    }

    ordered[0]
}
